        type: import("vue").PropType<(data: {
            record: TableData;
            column: TableColumnData | TableOperationColumn;
            rowIndex: number;
            columnIndex: number;
        }) => {
            rowspan?: number;
            colspan?: number;
        } | void>;
    };
    /**
     * @zh 是否让合并方法的索引包含所有
     * @en Whether to make the index of the span method contain all
     */
    spanAll: {
        type: BooleanConstructor;
        default: boolean;
    };
    components: {
        type: import("vue").PropType<TableComponents>;
    };
    /**
